          "gu": "દરેક વાળેલી રેખા એક **અરીસા** જેવી છે! જ્યારે કાગળ અડધો વાળીને ૧ કાણું પાડો, ત્યારે ખોલતાં તે સામે પણ દેખાય છે ($1 \\times 2 = 2$). બે વાર વાળવાથી ૧ કાણું **૪ કાણાં** બની જાય છે!"
